from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric.mlkem import MLKEM768PrivateKey
from cryptography.hazmat.primitives.asymmetric.x25519 import X25519PrivateKey, X25519PublicKey
from cryptography.hazmat.primitives.kdf.hkdf import HKDF
from kyber_py.ml_kem import ML_KEM_768

Q = 3329
RAW = dict(encoding=serialization.Encoding.Raw, format=serialization.PublicFormat.Raw)

class Abort(Exception):
    pass

def decode12(data):
    out = []
    for i in range(0, len(data), 3):
        b0, b1, b2 = data[i:i + 3]
        out += [b0 | (b1 & 15) << 8, (b1 >> 4) | b2 << 4]
    return out

def server_respond(client_share):
    if len(client_share) != 1216:
        raise Abort("illegal_parameter: client share has the wrong length")
    ek, x_peer = client_share[:1184], client_share[1184:]
    if any(c >= Q for c in decode12(ek[:1152])):
        raise Abort("illegal_parameter: ML-KEM encapsulation key check failed (FIPS 203, section 7.2)")
    ml_secret, ciphertext = ML_KEM_768.encaps(ek)
    x_private = X25519PrivateKey.generate()
    try:
        x_secret = x_private.exchange(X25519PublicKey.from_public_bytes(x_peer))
    except ValueError:
        raise Abort("illegal_parameter: X25519 shared secret check failed")
    return ciphertext + x_private.public_key().public_bytes(**RAW), ml_secret + x_secret         # ML-KEM secret first

class Client:
    def __init__(self):
        self.ml = MLKEM768PrivateKey.generate()
        self.x = X25519PrivateKey.generate()
    def share(self):
        return self.ml.public_key().public_bytes_raw() + self.x.public_key().public_bytes(**RAW)
    def finish(self, server_share):
        if len(server_share) != 1120:
            raise Abort("illegal_parameter: server share has the wrong length")
        try:
            x_secret = self.x.exchange(X25519PublicKey.from_public_bytes(server_share[1088:]))
        except ValueError:
            raise Abort("illegal_parameter: X25519 shared secret check failed")
        return self.ml.decapsulate(server_share[:1088]) + x_secret

client = Client()
client_share = client.share()
server_share, server_secret = server_respond(client_share)
client_secret = client.finish(server_share)
print("client share bytes:", len(client_share), "| server share bytes:", len(server_share), "| shared secret bytes:", len(client_secret))
print("both sides derive the same 64-byte hybrid secret:", client_secret == server_secret)

print("--- mandatory checks ---")
for label, action in (
    ("truncated client share", lambda: server_respond(client_share[:-1])),
    ("out-of-range ML-KEM coefficient", lambda: server_respond(b"\xff\xff\xff" + client_share[3:])),
    ("all-zero X25519 point", lambda: server_respond(client_share[:1184] + bytes(32))),
    ("truncated server share", lambda: client.finish(server_share[:-1])),
):
    try:
        action()
        print(f"{label}: accepted (this should not happen)")
    except Abort as error:
        print(f"{label}: aborted with {error}")

print("--- the hybrid secret depends on both parts ---")
def derive(secret):
    return HKDF(hashes.SHA256(), 32, None, b"lab hybrid key").derive(secret).hex()[:16]
ml_part, x_part = client_secret[:32], client_secret[32:]
base = derive(client_secret)
print("the same hybrid secret always gives the same key:", derive(client_secret) == base)
print("changing only the X25519 part changes the key:   ", derive(ml_part + bytes(32)) != base)
print("changing only the ML-KEM part changes the key:   ", derive(bytes(32) + x_part) != base)

# A migration plan from an inventory, using an explicit rule: an asset is urgent for confidentiality when
# (years it must stay confidential) + (years needed to migrate) exceeds (years until a quantum computer): the B8 rule.
ARRIVAL = 9                      # ASSUMPTION: a cryptographically relevant quantum computer in nine years (2035); vary it
INVENTORY = [                    # invented example assets
    # name, protects, key exchange / signature algorithm, confidentiality years, migration years, depends on
    ("patient portal",        "confidentiality", "ECDHE-P256",       25, 2, []),
    ("insurer VPN",           "confidentiality", "ECDHE-P256",       10, 3, ["vpn-gateway-firmware"]),
    ("backup key wrapping",   "confidentiality", "RSA-2048",         20, 4, []),
    ("public website",        "confidentiality", "X25519",            1, 1, []),
    ("code-signing root",     "authenticity",    "RSA-3072",          0, 5, ["build-pipeline"]),
    ("vpn-gateway-firmware",  "authenticity",    "ECDSA-P256",        0, 3, []),
    ("build-pipeline",        "authenticity",    "RSA-3072",          0, 3, []),
]
DEPRECATED_AFTER_2030 = {"RSA-2048"}                              # 112-bit strength (IR 8547 draft, Table 2 of SP 800-57)

def assess(name, protects, algorithm, confidential_years, migration_years):
    reasons, score = [], 0
    if protects == "confidentiality":
        overshoot = confidential_years + migration_years - ARRIVAL
        if overshoot > 0:
            score += 100 + overshoot
            reasons.append(f"harvest-now-decrypt-later: {confidential_years} + {migration_years} years exceeds the assumed {ARRIVAL} by {overshoot}")
        else:
            score += 10
            reasons.append(f"margin of {-overshoot} years under the assumed arrival; schedule with normal change")
    else:
        score += 40
        reasons.append("authentication: forgery needs a quantum computer at signing time, but long migrations need an early start" + (f" ({migration_years} years)" if migration_years >= 4 else ""))
    if algorithm in DEPRECATED_AFTER_2030:
        score += 20
        reasons.append("112-bit algorithm: proposed deprecation after 2030 (NIST IR 8547 draft)")
    return score, reasons

assets = {name: (protects, algorithm, c, m, deps) for name, protects, algorithm, c, m, deps in INVENTORY}
ranked = sorted(((assess(name, p, a, c, m), name) for name, (p, a, c, m, deps) in assets.items()), key=lambda item: (-item[0][0], item[1]))
print("PHASE 0 (now): fix hygiene that needs no code change, then keep the inventory current (rescan after every change)")
phase = {"1: hybrid key exchange for confidentiality at risk": [], "2: signature roots and PKI": [], "3: normal change window": []}
titles = list(phase)
level = {}
for (score, reasons), name in ranked:
    protects = assets[name][0]
    level[name] = 0 if score >= 100 else 1 if protects == "authenticity" else 2
details = {name: (score, list(reasons)) for (score, reasons), name in ranked}
changed = True
while changed:                                                    # a dependency must not be scheduled after what needs it
    changed = False
    for name, (protects, algorithm, c, m, deps) in assets.items():
        for dependency in deps:
            if level[dependency] > level[name]:
                level[dependency] = level[name]
                details[dependency][1].append(f"pulled into this phase because {name} depends on it")
                changed = True
for (score, reasons), name in ranked:
    phase[titles[level[name]]].append((name, details[name][0], details[name][1]))
for title, items in phase.items():
    print(f"PHASE {title}")
    for name, score, reasons in items:
        deps = assets[name][4]
        print(f"  {name} ({assets[name][1]}, score {score})" + (f", migrate after: {', '.join(deps)}" if deps else ""))
        for reason in reasons:
            print("      -", reason)
